<?php
require_once $workspace.'/models/CashierSchedule.php';
$_SESSION['user']=['id'=>1,'branch_id'=>1];
Setting::set('cashier_schedule_enforcement','1','security');
check(CashierSchedule::ready(),'schedule schema installed');
reject(fn()=>CashierSchedule::assertAccess(1,1),'cashier without schedule denied POS');
$scRole=(int)RecipeInventory::rows('SELECT role_id FROM user_roles WHERE user_id=1 LIMIT 1')[0]['role_id'];
$scPerm=(int)RecipeInventory::rows("SELECT id FROM permissions WHERE name='manage_cashier_schedules'")[0]['id'];
RecipeInventory::query('DELETE FROM role_permissions WHERE role_id=? AND permission_id=?','ii',[$scRole,$scPerm]);
reject(fn()=>CashierSchedule::save(0,1,1,'2026-10-16T08:00','2026-10-16T16:00','test'),'schedule management requires explicit permission');
RecipeInventory::query('INSERT IGNORE INTO role_permissions(role_id,permission_id) VALUES(?,?)','ii',[$scRole,$scPerm]);
reject(fn()=>CashierSchedule::configure(2,0,0),'schedule configuration cannot cross assigned branch');
reject(fn()=>CashierSchedule::configure(1,121,0),'schedule grace cannot exceed two hours');
reject(fn()=>CashierSchedule::save(0,1,1,'2026-02-30T08:00','2026-03-01T08:00',''),'invalid dates rejected');
reject(fn()=>CashierSchedule::save(0,1,1,'2026-10-16T08:00','2026-10-16T07:00',''),'end must follow start');
reject(fn()=>CashierSchedule::save(0,1,3,'2026-10-16T08:00','2026-10-16T16:00',''),'cashier from other branch cannot be assigned');
$scNow=new DateTimeImmutable('now',new DateTimeZone('Asia/Singapore'));
$scStart=$scNow->modify('-30 minutes')->format('Y-m-d H:i:s');$scEnd=$scNow->modify('+30 minutes')->format('Y-m-d H:i:s');
$scId=CashierSchedule::save(0,1,1,$scStart,$scEnd,'Scheduled cashier');
check(count(CashierSchedule::current(1,1))===1,'current scheduled cashier allowed in own branch');
reject(fn()=>CashierSchedule::assertAccess(1,2),'schedule does not allow other branch');
reject(fn()=>CashierSchedule::save(0,1,1,$scStart,$scEnd,'Overlap'),'overlapping schedules rejected');
$scCart=endpoint('pos_cart',['action'=>'clear']);check($scCart['success'],'scheduled user may access POS cart');
CashierSchedule::save($scId,1,1,$scStart,$scEnd,'Cancelled','cancelled');
$scCart=endpoint('pos_cart',['action'=>'clear']);check(!$scCart['success'],'schedule cancellation blocks direct POS endpoint');
$scPin=endpoint('pos_pin',['pin'=>'1234']);check(!$scPin['success'],'PIN cannot bypass cancelled schedule');
$scRaw=endpoint('pos_fresh_render',[],false);check(strpos($scRaw,'No active cashier schedule')!==false,'POS page blocks users without current schedule');
$scFutureStart=$scNow->modify('+10 minutes')->format('Y-m-d H:i:s');$scFutureEnd=$scNow->modify('+2 hours')->format('Y-m-d H:i:s');
CashierSchedule::save($scId,1,1,$scFutureStart,$scFutureEnd,'Future');
reject(fn()=>CashierSchedule::assertAccess(1,1),'future schedule not active before configured opening window');
CashierSchedule::configure(1,15,0);check(count(CashierSchedule::current(1,1))===1,'early grace permits access within configured window');
CashierSchedule::configure(1,0,0);
$scPastStart=$scNow->modify('-2 hours')->format('Y-m-d H:i:s');$scPastEnd=$scNow->modify('-10 minutes')->format('Y-m-d H:i:s');
CashierSchedule::save($scId,1,1,$scPastStart,$scPastEnd,'Ended');
reject(fn()=>CashierSchedule::assertAccess(1,1),'ended schedule denies POS');
CashierSchedule::configure(1,0,15);check(count(CashierSchedule::current(1,1))===1,'late grace permits access within configured window');
CashierSchedule::configure(1,0,0);CashierSchedule::save($scId,1,1,$scStart,$scEnd,'Active');
Setting::set('pos_drawer_integration','1','security');
RecipeInventory::query("UPDATE users SET pos_pin='1234' WHERE id=1");
$scPin=endpoint('pos_pin',['pin'=>'9999']);check(!$scPin['success'],'wrong POS PIN denied');
$scPin=endpoint('pos_pin',['pin'=>'1234']);check($scPin['success'],'scheduled cashier can verify personal PIN');
$scRaw=endpoint('pos_after_pin_render',[],false);check(strpos($scRaw,'pos-drawer-dialog')!==false,'verified PIN issues a working one-use page grant');
$scRaw=endpoint('pos_internal_render',[],false);check(strpos($scRaw,'pos-drawer-dialog')!==false,'internal category navigation does not require PIN again');
$scRaw=endpoint('pos_fresh_render',[],false);check(strpos($scRaw,'pos-drawer-dialog')===false && strpos($scRaw,'pos_pin.php')!==false,'fresh POS entry requires PIN even with previously verified session');
$scRaw=endpoint('pos_render',[],false);check(strpos($scRaw,'pos-navigation')!==false,'one-use PIN grant allows POS and installs internal navigation token');
$scRaw=endpoint('shift_render',[],false);check(strpos($scRaw,'Cashier schedules')!==false && strpos($scRaw,'cashierScheduleNew')!==false,'schedule tab and modal render for authorized manager');
Setting::set('pos_drawer_integration','1','security');
$scShift=CashShift::open($pdRegister,1,'10',bin2hex(random_bytes(16)));
CashierSchedule::save($scId,1,1,$scStart,$scEnd,'Cancelled while drawer open','cancelled');
reject(fn()=>RecipeInventory::atomic(fn()=>CashShift::context(1,1,true)),'schedule enforced inside checkout transaction');
$scState=CashShift::posState(1);check($scState['schedule_allowed']===false && $scState['shift']!==null,'live POS status blocks use without losing active drawer');
CashShift::close($scShift,'10','Schedule ended',bin2hex(random_bytes(16)));check(CashShift::detail($scShift)['status']!=='open','cashier may safely close existing drawer after schedule ends');
Setting::set('pos_drawer_integration','0','security');
$scNight=CashierSchedule::save(0,1,1,'2030-01-01T22:00','2030-01-02T06:00','Overnight');check($scNight>0,'overnight schedules supported');
Setting::set('cashier_schedule_enforcement','0','security');
